//! Byte-exact checks against vectors generated by python-validity on synthetic inputs
//! (`tools/oracle/gen_tls_vectors.py`).

use serde_json::Value;
use validity_proto::tls::*;

fn vectors() -> Value {
    serde_json::from_str(include_str!("vectors/tls.json")).unwrap()
}

fn b(v: &Value) -> Vec<u8> {
    hex::decode(v.as_str().unwrap()).unwrap()
}

fn a32(v: &Value) -> [u8; 32] {
    b(v).try_into().unwrap()
}

fn secret(v: &Value) -> p256::SecretKey {
    p256::SecretKey::from_slice(&b(v)).unwrap()
}

#[test]
fn prf_matches() {
    for c in vectors()["prf"].as_array().unwrap() {
        let len = c["len"].as_u64().unwrap() as usize;
        assert_eq!(prf(&b(&c["secret"]), &b(&c["seed"]), len), b(&c["out"]));
    }
}

#[test]
fn hs_key_matches() {
    assert_eq!(hs_key().to_vec(), b(&vectors()["hs_key"]));
}

#[test]
fn pad_roundtrip() {
    for c in vectors()["pad"].as_array().unwrap() {
        let padded = pad(&b(&c["in"]));
        assert_eq!(padded, b(&c["out"]));
        assert_eq!(unpad(&padded).unwrap(), b(&c["in"]).as_slice());
    }
    assert_eq!(unpad(&[]), Err(Error::BadPadding));
    assert_eq!(unpad(&[5, 5]), Err(Error::BadPadding));
}

#[test]
fn psk_and_priv_blob() {
    let v = vectors();
    let psk = PskKeys::from_hw(
        v["psk"]["product"].as_str().unwrap(),
        v["psk"]["serial"].as_str().unwrap(),
    );
    assert_eq!(psk.encryption, a32(&v["psk"]["encryption_key"]));
    assert_eq!(psk.validation, a32(&v["psk"]["validation_key"]));

    let blob = b(&v["priv_blob"]["blob"]);
    let d = psk.open_priv_blob(&blob).unwrap();
    assert_eq!(d.to_bytes().to_vec(), b(&v["priv_blob"]["d"]));

    let other = PskKeys::from_hw("ThinkPad Synthetic", "SYNTH0002");
    assert!(matches!(
        other.open_priv_blob(&blob),
        Err(Error::PairedElsewhere)
    ));
    let mut tampered = blob.clone();
    tampered[0] = 3;
    assert!(matches!(
        psk.open_priv_blob(&tampered),
        Err(Error::UnknownPrivKeyPrefix(3))
    ));
}

#[test]
fn flash_block_matches() {
    let v = &vectors()["flash_block"];
    assert_eq!(
        flash_block(v["id"].as_u64().unwrap() as u16, &b(&v["body"])),
        b(&v["out"])
    );
}

fn session() -> SessionKeys {
    let k = &vectors()["keys"];
    let mut x = b(&k["server_x"]);
    let mut y = b(&k["server_y"]);
    x.reverse();
    y.reverse();
    SessionKeys::derive(
        &secret(&k["eph_d"]),
        &public_key_le(&x, &y).unwrap(),
        &a32(&k["client_random"]),
        &a32(&k["server_random"]),
    )
}

#[test]
fn session_keys_match() {
    let k = &vectors()["keys"];
    let s = session();
    assert_eq!(s.master_secret.to_vec(), b(&k["master_secret"]));
    assert_eq!(s.sign, a32(&k["sign_key"]));
    assert_eq!(s.validation, a32(&k["validation_key"]));
    assert_eq!(s.encryption, a32(&k["encryption_key"]));
    assert_eq!(s.decryption, a32(&k["decryption_key"]));
}

#[test]
fn app_record_seal_and_open() {
    let v = &vectors()["app_record"];
    let s = session();
    let payload = b(&v["payload"]);
    let iv: [u8; 16] = b(&v["iv"]).try_into().unwrap();
    let rec = record(CONTENT_APP_DATA, &seal(&s, CONTENT_APP_DATA, &payload, &iv));
    assert_eq!(rec, b(&v["record"]));

    // The oracle opened it with the client keys in the server role; do the same.
    let mirrored = SessionKeys {
        decryption: s.encryption,
        validation: s.sign,
        ..s.clone()
    };
    let recs = split_records(&rec).unwrap();
    assert_eq!(recs.len(), 1);
    assert_eq!(recs[0].0, CONTENT_APP_DATA);
    assert_eq!(
        open(&mirrored, CONTENT_APP_DATA, recs[0].1).unwrap(),
        payload
    );

    let mut bad = recs[0].1.to_vec();
    let last = bad.len() - 17; // flip a byte in the second-to-last block: corrupts MAC
    bad[last] ^= 1;
    assert!(open(&mirrored, CONTENT_APP_DATA, &bad).is_err());
    assert!(open(&s, CONTENT_APP_DATA, recs[0].1).is_err());
}

#[test]
fn client_hello_matches() {
    let v = &vectors()["client_hello"];
    let hello = client_hello(&a32(&v["random"]));
    assert_eq!(hello, b(&v["msg"]));
    assert_eq!(record(CONTENT_HANDSHAKE, &hello), b(&v["record"]));
}

#[test]
fn finished_matches() {
    let v = &vectors()["finished"];
    let s = session();
    let hash: [u8; 32] = <sha2::Sha256 as sha2::Digest>::digest(b(&v["transcript"])).into();
    assert_eq!(
        handshake_msg(0x14, &s.verify_data(b"client finished", &hash)),
        b(&v["client"])
    );
    assert_eq!(
        s.verify_data(b"server finished", &hash).to_vec(),
        b(&v["server_verify"])
    );
}
